-- The terms of use, version 1 (published; a later version is a new row).
INSERT INTO "content_pages" ("id", "slug", "locale", "title", "body", "status", "version", "publishedAt", "createdAt", "updatedAt")
VALUES (gen_random_uuid(), 'tos', 'he', 'תקנון שימוש ומדיניות פרטיות', $tos${"blocks":[{"type":"heading","text":"תקנון שימוש ומדיניות פרטיות – אפליקציית עיצוב תכשיטים"},{"type":"paragraph","text":"ברוכים הבאים לאפליקציית עיצוב התכשיטים (להלן: \"האפליקציה\"), המופעלת ומנוהלת על ידי הנהלת האפליקציה ו/או החברה המפעילה (להלן: \"החברה\")."},{"type":"paragraph","text":"השימוש באפליקציה, על כל תכניה, הכלים הדיגיטליים, השירותים ומערכות העיצוב הכלולים בה, מותנה בהסכמתך המלאה והבלתי מסויגת לתנאים המפורטים בתקנון זה (להלן: \"התקנון\" או \"תנאי השימוש\")."},{"type":"paragraph","text":"גלישה, הרשמה, יצירת חשבון, העלאת קבצים או ביצוע פעולה כלשהי באפליקציה מהווים אישור והצהרה מצדך (להלן: \"המשתמש\") כי קראת את הוראות תקנון זה, הבנת אותן וכי אתה מסכים להן במלואן. אם אינך מסכים לתנאים אלו, כולם או חלקם, עליך לחדול לאלתר מכל שימוש באפליקציה ולהסירה ממכשירך."},{"type":"section","text":"חלק א': תקנון ותנאי שימוש","id":"terms"},{"type":"subheading","text":"1. כשירות, רישום ויצירת חשבון"},{"type":"item","text":"1.1. השימוש באפליקציה וההרשמה אליה מותרים אך ורק לאזרחים ותושבים מעל גיל 18 הכשירים לבצע פעולות משפטיות מחייבות, או לתאגיד משפטי הרשום כדין."},{"type":"item","text":"1.2. בעת הרישום לאפליקציה, יידרש המשתמש למסור פרטים מזהים אישיים, נכונים, מדויקים ומלאים (לרבות שם מלא, כתובת דואר אלקטרוני פעילה ומספר טלפון). מסירת פרטים כוזבים מהווה עבירה פלילית ואזרחית."},{"type":"item","text":"1.3. המשתמש אחראי באופן בלעדי ומלא על שמירת סודיות פרטי הגישה לחשבונו (שם המשתמש והסיסמה) ועל כל פעילות, נזק או שימוש שיבוצעו תחת חשבונו. המשתמש מתחייב להודיע לחברה באופן מיידי על כל חשש לשימוש בלתי מורשה בחשבונו."},{"type":"subheading","text":"2. העלאת מידע, תכני משתמש והסכמה להעלאה לרשת (User Generated Content)"},{"type":"item","text":"2.1. האפליקציה מאפשרת למשתמשים לעצב תכשיטים, להשתמש בכלי עריכה, להעלות קבצים, גרפיקות, מודלים בתלת-ממד, סקיצות ותמונות (להלן יחד: \"תכני המשתמש\")."},{"type":"item","text":"2.2. הסכמה מפורשת להעלאת מידע לרשת: המשתמש מצהיר, מאשר ומסכים בזאת כי העלאת תכני המשתמש ופרטיו לאפליקציה כרוכה בהעלאת מידע לרשת האינטרנט הפתוחה ולשרתי ענן מרוחקים (Cloud Services). המשתמש מודע לכך שעל אף שהחברה נוקטת באמצעי אבטחת מידע מתקדמים ומקובלים, אין חסינות מוחלטת מפני חדירות, פריצות, גישה בלתי מורשית או חשיפה של מידע ברשת, והחברה לא תישא בכל חבות במקרים אלו."},{"type":"item","text":"2.3. המשתמש מתחייב ומצהיר כי הוא בעל מלוא זכויות היוצרים והקניין הרוחני בתכני המשתמש המועלים על ידו, או כי בידיו רישיון תקף כדין להעלותם. חל איסור מוחלט להעלות תכנים המפרים זכויות יוצרים, סימני מסחר, סודות מסחריים, זכויות קניין רוחני או זכויות פרטיות של כל צד שלישי."},{"type":"item","text":"2.4. רישיון שימוש לחברה: הקניין הרוחני בעיצובים המקוריים של המשתמש נותר בבעלותו. יחד עם זאת, בעצם העלאת תכני המשתמש לאפליקציה, המשתמש מעניק לחברה רישיון בלתי הדיר, חינמי (ללא תמלוגים), כלל-עולמי, לא בלעדי ובלתי מוגבל בזמן, לאחסן, לשכפל, להציג, לעבד, לשנות ולשנות את גודלם או הפורמט של התכנים, והכל לצורך תפעול האפליקציה, מתן השירותים, הצגת העיצובים למשתמש ושיפור הכלים הטכנולוגיים של האפליקציה."},{"type":"subheading","text":"3. קניין רוחני של החברה והגנת תכנים"},{"type":"item","text":"3.1. כל זכויות היוצרים, סימני המסחר, הפטנטים, הסודות המסחריים והקניין הרוחני באפליקציה – לרבות אך לא רק: קודי מקור, קודי יעד, אלגוריתמים, ממשקי משתמש (UI/UX), כלי עיצוב דיגיטליים, הדמיות תלת-ממדיות, גרפיקות, בסיסי נתונים, טקסטים, וכן תמונות קטלוג מובנות של תכשיטים, אבני חן, יהלומים, חומרי גלם ורקעים – הינם רכושה הבלעדי של החברה (או של צדדים שלישיים שהעניקו לחברה רישיון שימוש כדין) ומוגנים על ידי חוקי זכויות יוצרים של מדינת ישראל ואמנות בינלאומיות."},{"type":"item","text":"3.2. חל איסור מוחלט להעתיק, לשכפל, להפיץ, למכור, להציג בפומבי, לתרגם, לבצע הנדסה לאחור (Reverse Engineering), להפיק קוד מקור, או לעשות כל שימוש מסחרי או אחר ברכיבי האפליקציה, בכלי העיצוב שלה או בתמונות הקטלוג המוצגות בה, ללא קבלת אישור מפורש, מראש ובכתב מהחברה."},{"type":"subheading","text":"4. רכישות, אמצעי תשלום ואבטחת סליקה פיננסית"},{"type":"item","text":"4.1. האפליקציה עשויה לאפשר למשתמשים לרכוש מנויים, שירותי פרימיום, או להזמין ייצור פיזי של התכשיטים שועצבו על ידם (להלן: \"השירותים בתשלום\")."},{"type":"item","text":"4.2. ביצוע הרכישות מותנה בהזנת אמצעי תשלום תקף (כרטיס אשראי, ארנק דיגיטלי או אמצעי אחר המאושר באפליקציה). המשתמש מצהיר כי הוא הבעלים החוקי או בעל הרשאה כדין לעשות שימוש באמצעי התשלום שהוזן."},{"type":"item","text":"4.3. הגנת מידע פיננסי וספקים חיצוניים: למען הסר ספק, החברה אינה שומרת ואינה מאחסנת את פרטי אמצעי התשלום המלאים של המשתמשים (כגון מספרי כרטיסי אשראי מלאים, קודי CVV וכיו\"ב) בשרתיה. כל פעולות הסליקה, עיבוד התשלומים והזנת פרטי האשראי מבוצעות ומנוהלות באופן בלעדי על ידי ספקי סליקה חיצוניים מורשים, העומדים בתקני אבטחת המידע המחמירים ביותר של תעשיית כרטיסי האשראי (תקן PCI-DSS)."},{"type":"item","text":"4.4. החברה לא תישא בכל חבות או אחריות לכל נזק, פגיעה באבטחה, כשל, עיכוב, אובדן מידע או תקלה שמקורם בספקי הסליקה החיצוניים או בחברות האשראי."},{"type":"subheading","text":"5. הגבלת חבות ופטור מאחריות (Limitation of Liability)"},{"type":"item","text":"5.1. האפליקציה, שירותיה, תכניה וכלי העיצוב הכלולים בה ניתנים לשימוש כמות שהם (As Is) וככל שיהיו זמינים (As Available), ללא כל התחייבות או מצג מצד החברה לגבי התאמתם למטרה מסוימת, רמת דיוקם או זמינותם הרציפה."},{"type":"item","text":"5.2. דיוק גרפי והדמיות: המשתמש מצהיר כי ידוע לו שהדמיות התכשיטים, התמונות, המודלים התלת-ממדיים והצבעים המוצגים על גבי מסכים דיגיטליים באפליקציה הם להמחשה בלבד. ייתכנו סטיית צבעים, שינויי פרופורציות, הבדלי טקסטורה או שינויים קלים אחרים בין ההדמיה הדיגיטלית לבין המוצר הפיזי במציאות (ככל שיוזמן מוצר פיזי), והחברה לא תהיה אחראית להבדלים אלו."},{"type":"item","text":"5.3. החברה, בעלי מניותיה, מנהליה, עובדיה או מי מטעמה לא יהיו אחראים בשום מקרה ומכוח כל עילה משפטית (חוזית, נזיקית או אחרת) לכל נזק ישיר, עקיף, מקרי, מיוחד, תוצאתי, עונשי או מיוחד, לרבות אך לא רק: הפסד רווחים, אובדן נתונים, פגיעה במוניטין, הפסקת עבודה או כשל במחשב/מכשיר נייד, הנובעים מהשימוש באפליקציה, מחוסר יכולת להשתמש בה, או מהסתמכות על תכניה."},{"type":"item","text":"5.4. העדר אחריות לפעילות צורפים וספקי צד שלישי (ניתוק קשר סיבתי): למען הסר כל ספק, ובהתאם להלכה הפסוקה בעניין פלטפורמות דיגיטליות המשמשות כזירת חיבור או כלי עזר טכנולוגי, החברה פועלת אך ורק כספקית של פלטפורמת עיצוב ותיווך טכנולוגי מובנית, ואינה חלק משרשרת הייצור הפיזית. תפקידה של האפליקציה ואחריותה של החברה מסתיימים באופן מוחלט וסופי ברגע שבו המשתמש (המעצב או הלקוח) מסיים את הליך העיצוב הדיגיטלי ו/או יוצר קשר עם צורף, יצרן או בית מלאכה (להלן: \"הצורף\") לצורך ביצוע ההזמנה הפיזית."},{"type":"paragraph","text":"החברה אינה אחראית, במישרין או בעקיפין, לתוצר הפיזי הסופי המסופק על ידי הצורף, לרבות אך לא רק: לטיב העבודה, איכות החומרים, רמת הגימור, פגמים בייצור, אי-התאמה בין המודל הדיגיטלי למוצר הממשי, עיכובים באספקה, או כל נזק כספי, עגמת נפש ופגיעה אחרת שייגרמו למשתמש כתוצאה מההתקשרות עם הצורף. המשתמש מצהיר כי ידוע לו שכל התקשרות, תשלום או הזמנה מול צורף מהווים חוזה עצמאי ונפרד לחלוטין בינו לבין הצורף, ולחברה לא תהיה כל חבות מכוח התקשרות זו."},{"type":"section","text":"חלק ב': מדיניות פרטיות והגנת המידע","id":"privacy"},{"type":"paragraph","text":"החברה מכבדת את פרטיות המשתמשים ומחויבת להגנה על המידע האישי שנמסר לה, בהתאם להוראות חוק הגנת הפרטיות, התשמ\"א-1981 ותקנותיו."},{"type":"subheading","text":"1. סוגי המידע הנאסף באפליקציה"},{"type":"item","text":"1.1. מידע שנמסר מרצון: מידע שהמשתמש מוסר באופן אקטיבי בעת הרישום, פתיחת החשבון או יצירת קשר (כגון שם מלא, כתובת דואר אלקטרוני, מספר טלפון, וכן קבצים, תמונות וסקיצות שהועלו על ידו לאפליקציה)."},{"type":"item","text":"1.2. מידע טכני אוטומטי: בעת השימוש באפליקציה, נאסף באופן אוטומטי מידע טכני וסטטיסטי שאינו מזהה את המשתמש אישית באופן ישיר, לרבות: כתובת IP, סוג מכשיר הקצה, מערכת ההפעלה, מזהי מכשיר ייחודיים, נתוני מיקום (ככל שהמשתמש אישר זאת במכשירו), הרגלי גלישה, דפים שנצפו ומשך השהות באפליקציה. מידע זה נאסף באמצעות קבצי Cookies, תגיות ומערכות אנליטיקה שונות."},{"type":"subheading","text":"2. מטרות השימוש במידע והגנתו"},{"type":"paragraph","text":"החברה תעשה שימוש במידע שנאסף אך ורק למטרות הבאות:"},{"type":"item","text":"2.1. תפעול, ניהול ואספקת שירותי האפליקציה, כלי העיצוב ועיבוד הזמנות המשתמש."},{"type":"item","text":"2.2. שיפור, פיתוח וייעול חווית המשתמש, הכלים הטכנולוגיים והתכנים המוצעים באפליקציה."},{"type":"item","text":"2.3. מתן שירות לקוחות, תמיכה טכנית ומענה לפניות המשתמשים."},{"type":"item","text":"2.4. מניעת הונאות, שימוש לרעה באפליקציה או פעילות בלתי חוקית, ואבטחת מערכות המידע של החברה."},{"type":"item","text":"2.5. דיוור ישיר ותוכן שיווקי: בכפוף לקבלת הסכמתו המפורשת והנפרדת של המשתמש כדין, החברה תהיה רשאית לשלוח למשתמש עדכונים, ניוזלטרים, הצעות שיווקיות וחומרים פרסומיים באמצעות דואר אלקטרוני, מסרונים (SMS) או התראות בדחיפה (Push Notifications). המשתמש רשאי לחזור בו מהסכמתו זו בכל עת ולבקש את הסרתו מרשימת התפוצה באמצעות לחיצה על קישור ההסרה או פנייה לשירות הלקוחות."},{"type":"subheading","text":"3. העברת מידע לצדדים שלישיים"},{"type":"paragraph","text":"החברה מתחייבת שלא למכור, לא להשכיר ולא למסור את המידע האישי של המשתמשים לצדדים שלישיים, למעט במקרים הבאים:"},{"type":"item","text":"3.1. לספקי שירותים, קבלני משנה ושותפים עסקיים חיצוניים המסייעים לחברה בתפעול השוטף של האפליקציה (כגון חברות אחסון שרתי ענן, ספקי מערכות שירות לקוחות, חברות סליקה, וחברות שילוח ולוגיסטיקה לצורך אספקת מוצרים פיזיים). ספקים אלו יקבלו גישה אך ורק למידע הדרוש להם לצורך ביצוע תפקידם והם מחויבים בשמירה על סודיות המידע."},{"type":"item","text":"3.2. במקרה של מחלוקת משפטית, טענה, תביעה, דרישה או הליכים משפטיים בין המשתמש לבין החברה או מי מטעמה."},{"type":"item","text":"3.3. על פי צו שיפוטי, דרישה של רשות מוסמכת או הוראת כל דין המחייבת את החברה למסור את המידע."},{"type":"item","text":"3.4. במקרה של שינוי מבני בחברה, כגון מיזוג, רכישה או מכירת פעילות החברה (כולה או חלקה) לצד שלישי, ובלבד שהיישות המשפטית הקולטת תקבל על עצמה את הוראות מדיניות פרטיות זו במלואן."},{"type":"subheading","text":"4. זכויות המשתמש לעיון, תיקון ומחיקה"},{"type":"item","text":"4.1. בהתאם לחוק הגנת הפרטיות, התשמ\"א-1981, כל משתמש זכאי לעיין במידע שעליו המוחזק במאגר המידע של החברה."},{"type":"item","text":"4.2. משתמש שמצא כי המידע שנשמר עליו אינו נכון, אינו שלם או אינו מעודכן, רשאי לפנות לחברה בבקשה לתקן את המידע או למחוק חשבון זה לחלוטין משרתי החברה."},{"type":"item","text":"4.3. פניות בנושא זה ובכל שאלה הנוגעת לפרטיות ניתן להפנות לשירות הלקוחות של החברה בדואר אלקטרוני: litvak_tzilla@hotmail.com"},{"type":"section","text":"חלק ג': שונות, סמכות שיפוט ודין חל","id":"general"},{"type":"subheading","text":"1. שינויים בתקנון ובמדיניות הפרטיות"},{"type":"item","text":"1.1. החברה שומרת לעצמה את הזכות הבלעדית לשנות, לעדכן, להוסיף או לגרוע מתנאי תקנון זה ומדיניות הפרטיות מעת לעת, בהתאם לשיקול דעתה המוחלט וללא צורך במתן הודעה מוקדמת."},{"type":"item","text":"1.2. הנוסח המחייב והתקף של התקנון הוא הנוסח המפורסם באפליקציה בעת השימוש בה על ידי המשתמש. מומלץ למשתמשים להתעדכן בנוסח התקנון מעת לעת. המשך השימוש באפליקציה לאחר עדכון התקנון מהווה הסכמה מלאה של המשתמש לתנאים המעודכנים."},{"type":"subheading","text":"2. הדין החל וסמכות שיפוט בלעדית"},{"type":"item","text":"2.1. על תקנון זה, מדיניות הפרטיות ועל כל מערכת היחסים המשפטית שבין המשתמש לבין החברה (לרבות פרשנות התקנון, תוקפו והפרתו) יחולו אך ורק דיניה של מדינת ישראל, ללא כללי ברירת הדין הבינלאומיים."},{"type":"item","text":"2.2. סמכות השיפוט המקומית הבלעדית והייחודית לדון בכל מחלוקת, תביעה או עניין הנובעים מתקנון זה או מהשימוש באפליקציה תהיה נתונה אך ורק לבתי המשפט המוסמכים במחוז המרכז, ישראל."},{"type":"paragraph","text":"גרסה 1 · עדכון אחרון: 20 באוקטובר 2026"}]}$tos$::jsonb, 'PUBLISHED', 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON CONFLICT ("slug", "locale", "version") DO NOTHING;
